def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider rows and columns bound equal-sized repeated cells.
    out = [row[:] for row in grid]
    divr = next(r for r,row in enumerate(grid) if all(v == 3 for v in row))
    divc = [c for c in range(w) if all(grid[r][c] == 3 for r in range(h))]
    rh = divr
    cw = divc[0]
    # The nonempty bottom-right compartment is the motif.
    motif = [row[divc[-1]+1:] for row in grid[divr+1:]]
    for r0 in range(0, h, rh+1):
        for c0 in range(0, w, cw+1):
            if r0 == divr and c0 == divc[-1]+1:
                continue
            for r in range(min(rh, h-r0)):
                for c in range(min(cw, w-c0)):
                    if motif[r][c] != 5:
                        out[r0+r][c0+c] = motif[r][c]
    return out
